INSERT INTO `faq_categories` (`id`, `name`, `order`, `status`, `created_at`, `updated_at`, `description`) VALUES
('3', 'Market Information &amp; Facilities', '1', 'published', '2026-08-16 16:16:07', '2026-08-16 16:16:07', 'General information about Green Alliance Enterprises Fruit & Vegetable Market, location, and facilities.'),
('4', 'Investor &amp; Allottee FAQs', '2', 'published', '2026-08-16 16:16:07', '2026-08-16 16:16:07', 'Information on commercial plots, booking, payment plans, possession, and allotment terms.');

