INSERT INTO `faqs` (`id`, `question`, `answer`, `category_id`, `status`, `created_at`, `updated_at`) VALUES
('11', 'What is Green Alliance Enterprises Fruit &amp; Vegetable Market?', '<p>Green Alliance Enterprises Fruit &amp; Vegetable Market is a professionally planned wholesale market in Ahmedpur East, developed for commission agents, wholesalers, retailers, farmers, vendors and other agriculture-related businesses. The project is approved by PAMRA and is being developed according to the approved layout plan and applicable regulations.</p>', '3', 'published', '2026-08-16 16:16:07', '2026-08-16 16:16:07'),
('12', 'Where is Green Alliance Enterprises located?', '<p>Green Alliance Enterprises Fruit &amp; Vegetable Market is located at Abbasia Chowk, approximately 0.5 km towards Bahawalpur Road, opposite Javed CNG Pump, Ahmedpur East. Its accessible location makes it convenient for traders and businesses from Ahmedpur East and surrounding areas.</p>', '3', 'published', '2026-08-16 16:16:07', '2026-08-16 16:16:07'),
('13', 'What facilities are available in the market?', '<p>The project is being developed with essential commercial and public facilities, including wide solid roads, boundary wall, auction platforms, sewerage system, electricity infrastructure, street lights, mosque and toilet facilities. These facilities are designed to create a spacious, organized and business-friendly wholesale market environment.</p>', '3', 'published', '2026-08-16 16:16:07', '2026-08-16 16:16:07'),
('14', 'Who can operate a business in Green Alliance Enterprises?', '<p>The market is designed for commission agents, wholesalers, retailers, agricultural traders and the general public. Businesses related to fruits, vegetables, seeds, fertilizers, agricultural inputs, packaging, grocery, food, transport and other supporting services may also establish operations subject to the applicable market and company rules.</p>', '3', 'published', '2026-08-16 16:16:07', '2026-08-16 16:16:07'),
('15', 'Are there any market, entry or parking charges?', '<p>Yes. Commission agents may be required to pay market fees according to PAMRA rules and regulations. Entry and parking charges may also apply to vehicles entering the market. Market functionaries must comply with applicable government, PAMRA and company regulations, including any required registration or licence fees.</p>', '3', 'published', '2026-08-16 16:16:07', '2026-08-16 16:16:07'),
('16', 'Who can purchase a commercial plot at Green Alliance Enterprises?', '<p>Commercial plots are offered to commission agents and the general public on an ownership basis. Allotment is made on a first-come, first-served basis, subject to availability, application requirements and the official terms and conditions of the project.</p>', '4', 'published', '2026-08-16 16:16:07', '2026-08-16 16:16:07'),
('17', 'What payment options are available?', '<p>Plots may be offered through cash, monthly, quarterly or installment payment plans, according to the applicable payment schedule. Buyers are responsible for making installments on time in accordance with their agreed schedule.</p>', '4', 'published', '2026-08-16 16:16:07', '2026-08-16 16:16:07'),
('18', 'When can I get possession of my plot?', '<p>According to the project terms, possession of the allotted plot can be handed over after payment of 25% of the total plot amount, subject to the applicable project conditions. A possession slip is issued to the allottee when possession is delivered.</p>', '4', 'published', '2026-08-16 16:16:07', '2026-08-16 16:16:07'),
('19', 'Can I transfer or sell my plot after allotment?', '<p>An allottee cannot transfer or sell the plot before taking possession without prior written permission from the developer. Where a transfer is permitted, outstanding payments must be cleared and the applicable transfer/documentation fee must be paid according to the official terms.</p>', '4', 'published', '2026-08-16 16:16:07', '2026-08-16 16:16:07'),
('20', 'Are there any additional charges apart from the plot price?', '<p>The plot price includes specified development charges; however, certain additional costs may remain payable by the allottee. These may include documentation and lease charges, electricity connection and meter charges, registration or licence fees, government-imposed charges, taxes, betterment charges and other departmental charges, where applicable.</p><p><strong>Regular installment payments are essential:</strong> Late payments may result in penalties and continued default may lead to cancellation in accordance with the official allotment agreement.</p><p><em><strong>Important Note:</strong> All bookings, allotments, possession, transfers, refunds, fees and payments are governed by the official Green Alliance Enterprises Terms &amp; Conditions, payment schedule, company bylaws and applicable PAMRA/government regulations. Applicants should review their allotment documents before making an investment decision.</em></p>', '4', 'published', '2026-08-16 16:16:07', '2026-08-16 16:16:07');

-- Table structure for `faqs_translations`
DROP TABLE IF EXISTS `faqs_translations`;
CREATE TABLE `faqs_translations` (
  `lang_code` varchar(20) NOT NULL,
  `faqs_id` bigint(20) unsigned NOT NULL,
  `question` text DEFAULT NULL,
  `answer` text DEFAULT NULL,
  PRIMARY KEY (`lang_code`,`faqs_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `jobs`
DROP TABLE IF EXISTS `jobs`;
CREATE TABLE `jobs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `queue` varchar(255) NOT NULL,
  `payload` longtext NOT NULL,
  `attempts` tinyint(3) unsigned NOT NULL,
  `reserved_at` int(10) unsigned DEFAULT NULL,
  `available_at` int(10) unsigned NOT NULL,
  `created_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `jobs_queue_index` (`queue`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `language_meta`
DROP TABLE IF EXISTS `language_meta`;
CREATE TABLE `language_meta` (
  `lang_meta_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `lang_meta_code` varchar(20) DEFAULT NULL,
  `lang_meta_origin` varchar(32) NOT NULL,
  `reference_id` bigint(20) unsigned NOT NULL,
  `reference_type` varchar(120) NOT NULL,
  PRIMARY KEY (`lang_meta_id`),
  KEY `language_meta_reference_id_index` (`reference_id`),
  KEY `meta_code_index` (`lang_meta_code`),
  KEY `meta_origin_index` (`lang_meta_origin`),
  KEY `meta_reference_type_index` (`reference_type`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

