  `reference_type` varchar(255) DEFAULT NULL,
  `url` varchar(255) DEFAULT NULL,
  `icon_font` varchar(255) DEFAULT NULL,
  `position` tinyint(3) unsigned NOT NULL DEFAULT 0,
