-- Table structure for `newsletters`
DROP TABLE IF EXISTS `newsletters`;
CREATE TABLE `newsletters` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `email` varchar(120) NOT NULL,
  `name` varchar(120) DEFAULT NULL,
  `status` varchar(60) NOT NULL DEFAULT 'subscribed',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `pages`
DROP TABLE IF EXISTS `pages`;
CREATE TABLE `pages` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(120) NOT NULL,
  `content` longtext DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `template` varchar(60) DEFAULT NULL,
  `description` varchar(400) DEFAULT NULL,
  `status` varchar(60) NOT NULL DEFAULT 'published',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pages_user_id_index` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `pages` (`id`, `name`, `content`, `user_id`, `image`, `template`, `description`, `status`, `created_at`, `updated_at`) VALUES
('1', 'Homepage 1', '[hero-banner style=\"2\" transparent_header=\"yes\" title=\"Find Your\" title_color=\"#ffffff\" animation_text=\"Beautiful Dreams ,Prime Location Shops, Health Friendly Products\" animation_text_color=\"rgb(0, 255, 0)\" description=\"Create a realistic square blog-feature image for Green Alliance Enterprises showing a modern fruit and vegetable wholesale market in Ahmed Pur East, Pakistan. Show a spacious market entrance, fresh produce stalls, wholesalers unloading fruits and vegetables from trucks, commission agents and small retailers trading, wide internal roads, large covered sheds, and a clean open environment. Include a professional business atmosphere, bright daylight, realistic details, and subtle branding for Green Alliance Enterprises. The image should visually suggest connection with Rahim Yar Khan, Liaqat Pur, and Ahmed Pur East. Square format, website blog style, high quality.\" description_color=\"#ffffff\" background_image=\"hero-ape.jpg\" search_box_enabled=\"no\" tabs=\"project,rent,sale\" default_search_type=\"rent\" slider_image_1=\"639391445-122269240472281267-7572357059632137377-n.jpg\" slider_image_2=\"642356014-122269240430281267-4129079033260978465-n.jpg\" slider_image_3=\"599929218-122255228882281267-5563096775714299068-n.jpg\" slider_image_4=\"597865261-122255228942281267-6449561619390808534-n.jpg\" rotation_interval=\"10\" enable_rotation=\"yes\"][/hero-banner]\n\n[services style=\"1\" title=\"What We Offer?\" subtitle=\"OUR OPPORTUNITIES\" background_color=\"transparent\" services_quantity=\"3\" services_title_1=\"Wholesale Fruit & Vegetable Market\" services_description_1=\"A modern marketplace connecting wholesalers, commission agents, retailers and vendors for efficient daily trading of fresh fruits and vegetables.\" services_icon_1=\"ti ti-shopping-bag-search\" services_icon_image_1=\"pages/service-1.png\" services_button_url_1=\"/\" services_title_2=\"Shops for Traders & Businesses\" services_description_2=\"Small and large commercial shops are available for commission agents, agricultural suppliers, grocery stores, food outlets and other market-related businesses.\" services_icon_image_2=\"pages/service-2.png\" services_button_url_2=\"/\" services_title_3=\"Easy Shop Ownership\" services_description_3=\"Start your business with just 25% down payment, get possession of your shop and pay the remaining amount through an easy 3-year installment plan.\" services_icon_image_3=\"pages/service-3.png\" services_button_label_3=\"Learn More\" services_button_url_3=\"/\" icon_image_size=\"80\" counters_quantity=\"3\" counters_label_1=\"DOWN PAYMENT\" counters_number_1=\"25%\" counters_label_2=\"INSTALLMENT PLAN\" counters_number_2=\"3 YEARS\" counters_label_3=\"SHOPS\" counters_number_3=\"18×40 FT\" counters_label_4=\"MONTHLY TRAFFIC\" counters_number_4=\"66\" button_label=\"View All Services\" button_url=\"/\" centered_content=\"yes\" enable_lazy_loading=\"yes\"][/services]\n\n[services style=\"2\" title=\"Why Choose Green Alliance Enterprises?\" subtitle=\"OUR ADVANTAGES\" background_color=\"#f7f7f7\" services_quantity=\"3\" services_title_1=\"PAMRA-Approved Market\" services_description_1=\"A professionally planned fruit and vegetable market developed with regulatory approval, creating a reliable and organized business environment for traders, commission agents, retailers and investors.\" services_icon_image_1=\"images-removebg-preview.png\" services_title_2=\"Modern Trading Infrastructure\" services_description_2=\"Wide internal roads, spacious surroundings, dedicated auction areas and large covered sheds provide the space and facilities needed for smooth wholesale trading and daily market operations.\" services_icon_image_2=\"pages/service-2.png\" services_title_3=\"Business-Ready Facilities\" services_description_3=\"Commercial shops are supported with electricity infrastructure and essential market facilities, while flexible ownership options make it easier for entrepreneurs to establish and grow their businesses.\" services_icon_image_3=\"pages/service-3.png\" icon_image_size=\"80\" counters_quantity=\"1\" centered_content=\"yes\" enable_lazy_loading=\"yes\"][/services]\n\n[location style=\"4\" title=\"Already Our Running Locations\" subtitle=\"Explore Cities\" type=\"state\" state_ids=\"11,12,13\" destination=\"project\" background_color=\"#f7f7f7\" is_autoplay=\"yes\" autoplay_speed=\"3000\" is_loop=\"yes\" enable_lazy_loading=\"yes\"][/location]\n\n[faqs style=\"3\" title=\"Frequently Asked Questions\" subtitle=\"Find answers about Green Alliance Enterprises, market facilities, commercial plots, investment plans, possession, payments and allotment terms.\" display_type=\"group\" limit=\"10\" expand_first_time=\"yes\" enable_lazy_loading=\"yes\"][/faqs]\n\n[blog-posts style=\"1\" title=\"Helpful GAE Guides\" subtitle=\"Latest News\" type=\"recent\" limit=\"3\" background_color=\"#f7f7f7\" enable_lazy_loading=\"yes\"][/blog-posts]', '1', NULL, 'full-width', NULL, 'published', '2026-05-29 08:48:46', '2026-08-16 23:06:45'),
('2', 'Homepage 2', '[hero-banner style=\"2\" title=\"Find A Home That\" animation_text=\"Perfectly,Dream Home\" description=\"We are a real estate agency that will help you find the best residence you dream of.\" background_image=\"pages/slider-left.jpg\" slider_image_1=\"pages/slider-2.jpg\" slider_image_2=\"pages/slider-3.jpg\" slider_image_3=\"pages/slider-4.jpg\" slider_image_4=\"pages/slider-5.jpg\" search_box_enabled=\"1\" projects_search_enabled=\"1\" default_search_type=\"project\"][/hero-banner]\n[property-categories style=\"1\" title=\"Try Searching For\" subtitle=\"PROPERTY TYPE\" category_ids=\"1,2,3,4,5,6\" background_color=\"transparent\" button_label=\"View All\" button_url=\"/categories\" enable_lazy_loading=\"yes\"][/property-categories]\n[properties style=\"4\" title=\"Discover Homzen\'s Finest Properties For Your Dream Home\" subtitle=\"Featured Properties\" limit=\"8\" button_label=\"View All Properties\" button_url=\"/properties\" enable_lazy_loading=\"yes\"][/properties]\n[services style=\"3\" title=\"Discover What Sets Our Real Estate Expertise Apart\" subtitle=\"Why Choose Us\" description=\"At Homzen, our unwavering commitment lies in crafting unparalleled real estate journeys. Our seasoned professionals, armed with extensive market knowledge, walk alongside you through every phase of your property endeavor. We prioritize understanding your unique aspirations, tailoring our expertise to match your vision.\" checklist=\"Transparent Partnerships,Proven Expertise,Customized Solutions,Local Area Knowledge\" background_color=\"#f7f7f7\" services_quantity=\"3\" services_title_1=\"Buy A New Home\" services_description_1=\"Discover your dream home effortlessly. Explore diverse properties and expert guidance for a seamless buying experience.\" services_button_label_1=\"Learn More\" services_button_url_1=\"/\" services_icon_image_1=\"pages/service-1.png\" services_title_2=\"Rent A Home\" services_description_2=\"Discover your perfect rental effortlessly. Explore a diverse variety of listings tailored precisely to suit your unique lifestyle needs.\" services_button_label_2=\"Learn More\" services_button_url_2=\"/\" services_icon_image_2=\"pages/service-2.png\" services_title_3=\"Sell A Home\" services_description_3=\"Sell confidently with expert guidance and effective strategies, showcasing your property\'s best features for a successful sale.\" services_button_label_3=\"Learn More\" services_button_url_3=\"/\" services_icon_image_3=\"pages/service-3.png\" counters_quantity=\"1\" button_label=\"Contact Us\" button_url=\"/contact-us\" centered_content=\"\" enable_lazy_loading=\"yes\"][/services]\n[location style=\"2\" title=\"Our Location For You\" subtitle=\"Explore States\" type=\"state\" state_ids=\"1,2,3,4,5,6\" destination=\"property\" background_color=\"transparent\" enable_lazy_loading=\"yes\"][/location]\n[properties style=\"3\" title=\"Best Property Value\" subtitle=\"Top Properties\" is_featured=\"1\" limit=\"4\" button_label=\"View All\" button_url=\"/properties\" enable_lazy_loading=\"yes\" background_color=\"#f7f7f7\"][/properties]\n[agents style=\"1\" title=\"Meet Our Agents\" subtitle=\"Our Teams\" account_ids=\"1,2,3,4\" enable_lazy_loading=\"yes\"][/agents]\n[mortgage-calculator style=\"default\" layout=\"horizontal\" form_style=\"modern\" form_size=\"xl\" form_alignment=\"center\" form_margin=\"50px 0\" form_title=\"Mortgage Calculator\" form_description=\"Calculate your monthly mortgage payments\" background_color=\"#f7f7f7\" enable_lazy_loading=\"yes\"][/mortgage-calculator]\n[testimonials style=\"3\" title=\"What\'s People Say\'s\" subtitle=\"Our Testimonials\" description=\"Our seasoned team excels in real estate with years of successful market navigation, offering informed decisions and optimal results.\" testimonial_ids=\"1,2,3,4\" enable_lazy_loading=\"yes\"][/testimonials]\n[blog-posts style=\"1\" title=\"Helpful Homzen Guides\" subtitle=\"Latest News\" type=\"recent\" limit=\"3\" enable_lazy_loading=\"yes\"][/blog-posts]', '1', NULL, 'full-width', NULL, 'pending', '2026-05-29 08:48:46', '2026-08-16 15:45:45'),
