INSERT INTO `re_projects` (`id`, `name`, `description`, `content`, `images`, `floor_plans`, `location`, `investor_id`, `number_block`, `number_floor`, `number_flat`, `is_featured`, `featured_priority`, `date_finish`, `date_sell`, `price_from`, `price_to`, `currency_id`, `city_id`, `status`, `author_id`, `author_type`, `created_at`, `updated_at`, `latitude`, `longitude`, `zip_code`, `views`, `country_id`, `state_id`, `unique_id`, `private_notes`) VALUES
('1', 'Walnut Park Apartments', 'Modern urban living at its finest with sleek design, smart features, and a commitment to sustainable development.', 'Welcome to our flagship development project, a masterfully planned community that sets new standards for modern living. This exceptional project features a diverse range of residential options, from cozy apartments to spacious family homes, all designed with attention to detail and quality construction. Residents enjoy access to world-class amenities including a state-of-the-art fitness center, swimming pools, landscaped gardens, and community gathering spaces. The development incorporates sustainable building practices and energy-efficient systems, reflecting our commitment to environmental responsibility. Located in a prime area with excellent connectivity to schools, shopping centers, healthcare facilities, and public transportation, this project offers the perfect balance of convenience and tranquility. Our experienced development team has created a community where families can thrive, professionals can unwind, and investors can expect strong returns. With flexible payment plans and competitive pricing, this is an opportunity not to be missed.', '[\"properties\\/1.jpg\",\"properties\\/2.jpg\",\"properties\\/3.jpg\",\"properties\\/4.jpg\",\"properties\\/5.jpg\",\"properties\\/6.jpg\",\"properties\\/7.jpg\",\"properties\\/9.jpg\",\"properties\\/10.jpg\",\"properties\\/12.jpg\"]', NULL, '250 Parkview Boulevard, Central Heights', '9', '7', '36', '4190', '0', '0', '2027-06-29', '2025-05-29', '2508', '5929', '1', '3', 'selling', '1', 'Botble\\ACL\\Models\\User', '2026-05-29 08:48:43', '2026-05-29 08:48:43', '43.1967', '-75.7862', NULL, '9445', '3', '3', 'EG960Q', NULL),
('2', 'Sunshine Wonder Villas', 'A premier residential development offering modern living with exceptional amenities and thoughtful design in a prime location.', 'Discover a new standard of community living in this thoughtfully designed development project. Spanning multiple phases, this ambitious project creates a self-contained neighborhood with all the conveniences of modern life. The architectural design draws inspiration from contemporary trends while incorporating timeless elements that ensure lasting appeal. Residents enjoy exclusive access to premium amenities including clubhouse facilities, sports courts, children play areas, and jogging trails. The development places strong emphasis on green spaces and environmental sustainability, with extensive landscaping and eco-friendly building systems. The location offers strategic advantages including proximity to employment centers, quality schools, healthcare facilities, and shopping destinations. Our development team brings decades of experience in creating successful residential communities, ensuring that every detail meets the highest standards. This is more than a place to live – it is a community designed for life.', '[\"properties\\/1.jpg\",\"properties\\/2.jpg\",\"properties\\/3.jpg\",\"properties\\/4.jpg\",\"properties\\/5.jpg\",\"properties\\/6.jpg\",\"properties\\/7.jpg\",\"properties\\/8.jpg\",\"properties\\/9.jpg\",\"properties\\/10.jpg\",\"properties\\/12.jpg\"]', NULL, '250 Parkview Boulevard, Central Heights', '1', '2', '28', '2995', '0', '0', '2028-08-29', '2026-04-29', '9490', '17754', '1', '5', 'selling', '1', 'Botble\\ACL\\Models\\User', '2026-05-29 08:48:43', '2026-05-29 08:48:43', '43.473', '-76.1839', NULL, '1456', '5', '5', 'N37Y2A', NULL),
('3', 'Diamond Island', 'Modern urban living at its finest with sleek design, smart features, and a commitment to sustainable development.', 'Discover a new standard of community living in this thoughtfully designed development project. Spanning multiple phases, this ambitious project creates a self-contained neighborhood with all the conveniences of modern life. The architectural design draws inspiration from contemporary trends while incorporating timeless elements that ensure lasting appeal. Residents enjoy exclusive access to premium amenities including clubhouse facilities, sports courts, children play areas, and jogging trails. The development places strong emphasis on green spaces and environmental sustainability, with extensive landscaping and eco-friendly building systems. The location offers strategic advantages including proximity to employment centers, quality schools, healthcare facilities, and shopping destinations. Our development team brings decades of experience in creating successful residential communities, ensuring that every detail meets the highest standards. This is more than a place to live – it is a community designed for life.', '[\"properties\\/1.jpg\",\"properties\\/2.jpg\",\"properties\\/3.jpg\",\"properties\\/4.jpg\",\"properties\\/6.jpg\",\"properties\\/7.jpg\",\"properties\\/8.jpg\",\"properties\\/9.jpg\",\"properties\\/10.jpg\"]', NULL, '250 Parkview Boulevard, Central Heights', '14', '7', '35', '2334', '1', '0', '2029-01-29', '2026-03-01', '2828', '5220', '1', '3', 'selling', '1', 'Botble\\ACL\\Models\\User', '2026-05-29 08:48:43', '2026-05-29 08:48:43', '43.5907', '-75.4265', NULL, '1629', '3', '3', 'XXVULT', NULL),
('4', 'The Nassim', 'Modern urban living at its finest with sleek design, smart features, and a commitment to sustainable development.', 'Welcome to our flagship development project, a masterfully planned community that sets new standards for modern living. This exceptional project features a diverse range of residential options, from cozy apartments to spacious family homes, all designed with attention to detail and quality construction. Residents enjoy access to world-class amenities including a state-of-the-art fitness center, swimming pools, landscaped gardens, and community gathering spaces. The development incorporates sustainable building practices and energy-efficient systems, reflecting our commitment to environmental responsibility. Located in a prime area with excellent connectivity to schools, shopping centers, healthcare facilities, and public transportation, this project offers the perfect balance of convenience and tranquility. Our experienced development team has created a community where families can thrive, professionals can unwind, and investors can expect strong returns. With flexible payment plans and competitive pricing, this is an opportunity not to be missed.', '[\"properties\\/1.jpg\",\"properties\\/3.jpg\",\"properties\\/4.jpg\",\"properties\\/5.jpg\",\"properties\\/7.jpg\",\"properties\\/8.jpg\",\"properties\\/9.jpg\",\"properties\\/10.jpg\",\"properties\\/12.jpg\"]', NULL, '250 Parkview Boulevard, Central Heights', '7', '10', '49', '1801', '0', '0', '2027-03-01', '2025-12-29', '9020', '15834', '1', '6', 'selling', '1', 'Botble\\ACL\\Models\\User', '2026-05-29 08:48:43', '2026-05-29 08:48:43', '43.181', '-74.962', NULL, '5931', '6', '6', 'EOSJ69', NULL);

