-- Table structure for `re_properties`
DROP TABLE IF EXISTS `re_properties`;
CREATE TABLE `re_properties` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(300) NOT NULL,
  `type` varchar(20) NOT NULL DEFAULT 'sale',
  `description` varchar(400) DEFAULT NULL,
  `content` longtext DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `images` text DEFAULT NULL,
  `floor_plans` longtext DEFAULT NULL,
  `project_id` bigint(20) unsigned DEFAULT 0,
  `number_bedroom` decimal(8,1) DEFAULT 0.0,
  `number_bathroom` decimal(8,1) DEFAULT 0.0,
  `number_floor` int(11) DEFAULT NULL,
  `square` double DEFAULT NULL,
  `price` decimal(15,2) DEFAULT NULL,
  `currency_id` bigint(20) unsigned DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `featured_priority` int(11) DEFAULT 0,
  `city_id` bigint(20) unsigned DEFAULT NULL,
  `period` varchar(30) NOT NULL DEFAULT 'month',
  `status` varchar(60) NOT NULL DEFAULT 'selling',
  `author_id` bigint(20) unsigned DEFAULT NULL,
  `author_type` varchar(255) NOT NULL DEFAULT 'Botble\\ACL\\Models\\User',
  `moderation_status` varchar(60) NOT NULL DEFAULT 'pending',
  `reject_reason` varchar(400) DEFAULT NULL,
  `expire_date` date DEFAULT NULL,
  `auto_renew` tinyint(1) NOT NULL DEFAULT 0,
  `never_expired` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `latitude` varchar(25) DEFAULT NULL,
  `longitude` varchar(25) DEFAULT NULL,
  `zip_code` varchar(20) DEFAULT NULL,
  `views` int(10) unsigned NOT NULL DEFAULT 0,
  `country_id` bigint(20) unsigned DEFAULT 1,
  `state_id` bigint(20) unsigned DEFAULT NULL,
  `unique_id` varchar(255) DEFAULT NULL,
  `private_notes` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `re_properties_unique_id_unique` (`unique_id`),
  KEY `idx_re_properties_status` (`status`),
  KEY `idx_re_properties_location` (`location`),
  KEY `idx_re_properties_city_status` (`city_id`,`status`),
  KEY `idx_re_properties_state_status` (`state_id`,`status`),
  KEY `idx_re_properties_featured_sort` (`is_featured`,`featured_priority`,`created_at`),
  KEY `idx_re_properties_moderation_status` (`moderation_status`),
  KEY `idx_re_properties_expire_date` (`expire_date`),
  KEY `idx_re_properties_type` (`type`),
  KEY `idx_re_properties_never_expired` (`never_expired`),
  KEY `idx_re_properties_mod_status` (`moderation_status`,`status`),
  KEY `idx_re_properties_price` (`price`),
  KEY `idx_re_properties_square` (`square`),
  KEY `idx_re_properties_bedroom` (`number_bedroom`),
  KEY `idx_re_properties_bathroom` (`number_bathroom`),
  KEY `idx_re_properties_floor` (`number_floor`),
  KEY `idx_re_properties_project_id` (`project_id`),
  KEY `idx_re_properties_author` (`author_id`,`author_type`),
  KEY `idx_re_properties_country_id` (`country_id`),
  KEY `idx_re_properties_currency_id` (`currency_id`),
  KEY `idx_re_properties_active_featured_sort` (`moderation_status`,`status`,`expire_date`,`never_expired`,`is_featured`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=62 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `re_properties` (`id`, `name`, `type`, `description`, `content`, `location`, `images`, `floor_plans`, `project_id`, `number_bedroom`, `number_bathroom`, `number_floor`, `square`, `price`, `currency_id`, `is_featured`, `featured_priority`, `city_id`, `period`, `status`, `author_id`, `author_type`, `moderation_status`, `reject_reason`, `expire_date`, `auto_renew`, `never_expired`, `created_at`, `updated_at`, `latitude`, `longitude`, `zip_code`, `views`, `country_id`, `state_id`, `unique_id`, `private_notes`) VALUES
('37', 'Evergreen Terrace', 'sale', 'Spacious and bright residence with an excellent layout for modern living. Move-in ready with all appliances included.', 'This stunning residence offers an unparalleled living experience in one of the most desirable locations. The thoughtfully designed floor plan maximizes space and functionality while maintaining an elegant aesthetic. Upon entering, you are greeted by soaring ceilings and an abundance of natural light that highlights the premium finishes throughout. The chef-inspired kitchen features top-of-the-line appliances, a large center island, and ample storage. The living areas are perfect for both intimate gatherings and large-scale entertaining. Each bedroom is generously sized with excellent closet space. The primary suite includes a luxurious bathroom with dual vanities, a soaking tub, and a separate shower. Outside, the property boasts professional landscaping, a private backyard, and a covered outdoor entertaining area. Smart home features, energy-efficient systems, and a two-car garage complete this exceptional offering.', '741 Hickory Place, Forest Glen', '[\"properties\\/1.jpg\",\"properties\\/2.jpg\",\"properties\\/3.jpg\",\"properties\\/4.jpg\",\"properties\\/5.jpg\",\"properties\\/6.jpg\",\"properties\\/7.jpg\",\"properties\\/8.jpg\",\"properties\\/9.jpg\",\"properties\\/10.jpg\",\"properties\\/11.jpg\",\"properties\\/12.jpg\"]', '[{\"name\":{\"key\":\"name\",\"value\":\"First Floor\"},\"bedrooms\":{\"key\":\"bedrooms\",\"value\":\"3\"},\"bathrooms\":{\"key\":\"bathrooms\",\"value\":\"2\"},\"image\":{\"key\":\"image\",\"value\":\"properties\\/floor.png\"}},{\"name\":{\"key\":\"name\",\"value\":\"Second Floor\"},\"bedrooms\":{\"key\":\"bedrooms\",\"value\":\"2\"},\"bathrooms\":{\"key\":\"bathrooms\",\"value\":\"1\"},\"image\":{\"key\":\"image\",\"value\":\"properties\\/floor.png\"}}]', '3', '9.0', '10.0', '26', '650', '592600.00', NULL, '0', '0', '4', 'month', 'selling', '1', 'Botble\\RealEstate\\Models\\Account', 'approved', NULL, '2027-04-20', '0', '1', '2026-05-29 08:48:44', '2026-05-29 08:48:44', '43.8551', '-75.1538', NULL, '48616', '4', '4', '2B8DI3', NULL),
('38', 'Golden Gate Residences', 'rent', 'Meticulously maintained property with upgrades throughout. Features include hardwood floors, granite countertops, and stainless appliances.', 'Welcome to this exceptional property that redefines modern living. From the moment you enter, you will be captivated by the attention to detail and quality craftsmanship evident throughout. The open-concept living area flows seamlessly into the gourmet kitchen, featuring premium appliances, quartz countertops, and custom cabinetry. Large windows flood the space with natural light while offering views of the beautifully landscaped surroundings. The primary suite is a true retreat, complete with a spa-like bathroom and generous walk-in closet. Additional bedrooms are well-appointed, perfect for family members or guests. The outdoor living space extends your entertaining options with a covered patio and mature landscaping. Located in a sought-after neighborhood with excellent schools, convenient shopping, and easy highway access, this property offers the perfect combination of comfort, style, and location.', '654 Birch Boulevard, Sunset Hills', '[\"properties\\/2.jpg\",\"properties\\/3.jpg\",\"properties\\/6.jpg\",\"properties\\/9.jpg\",\"properties\\/10.jpg\",\"properties\\/12.jpg\"]', '[{\"name\":{\"key\":\"name\",\"value\":\"First Floor\"},\"bedrooms\":{\"key\":\"bedrooms\",\"value\":\"3\"},\"bathrooms\":{\"key\":\"bathrooms\",\"value\":\"2\"},\"image\":{\"key\":\"image\",\"value\":\"properties\\/floor.png\"}},{\"name\":{\"key\":\"name\",\"value\":\"Second Floor\"},\"bedrooms\":{\"key\":\"bedrooms\",\"value\":\"2\"},\"bathrooms\":{\"key\":\"bathrooms\",\"value\":\"1\"},\"image\":{\"key\":\"image\",\"value\":\"properties\\/floor.png\"}}]', '0', '3.0', '1.0', '67', '690', '470600.00', NULL, '0', '0', '1', 'month', 'renting', '6', 'Botble\\RealEstate\\Models\\Account', 'approved', NULL, '2026-10-02', '0', '1', '2026-05-29 08:48:44', '2026-08-16 09:59:54', '43.7953', '-76.0376', NULL, '16017', '1', '1', 'JFNWER', NULL),
('39', 'Green Alliance Enterprises – A New Business Opportunity in Ahmed Pur East', 'sale', 'Green Alliance Enterprises is introducing a modern fruit and vegetable market designed to create new business opportunities for traders, commission agents, wholesalers, retailers, and investors. Located in Ahmed Pur East, this developing market is planned to serve not only the local area but also surrounding business communities including Rahim Yar Khan and Liaqat Pur.', '<p class=\"isSelectedEnd\"><span>The purpose of this market is simple: to create an organized, spacious, and business-friendly environment where fresh produce trading can take place smoothly and efficiently. Every morning, large wholesalers and suppliers can bring fruits and vegetables to the market, while commission agents and small retailers can purchase stock in a well-managed setting. This model creates value for all levels of the supply chain and helps build a strong commercial ecosystem.</span></p><p class=\"isSelectedEnd\"><span>One of the biggest strengths of Green Alliance Enterprises is its focus on convenience and infrastructure. The market is being developed with wide internal roads, open surroundings, and dedicated spaces that support the movement of trucks, loading and unloading, and daily wholesale activity. Large covered sheds are planned for wholesalers, commission agents, and auction-related trading, helping businesses operate more comfortably and professionally.</span></p><p class=\"isSelectedEnd\"><span>For entrepreneurs and investors, Green Alliance Enterprises also offers commercial shop opportunities. Whether someone wants to establish a fruit business, vegetable trade office, seed and pesticide outlet, grocery store, packaging unit, tea stall, transport office, or other support business, the market provides a promising location to start and grow. Small and large shops are available to suit different business needs.</span></p><p class=\"isSelectedEnd\"><span>The project becomes even more attractive because of its accessible ownership plan. Businesses can secure a shop with a <strong>25% down payment</strong>, receive possession, and continue with an easy <strong>3-year installment plan</strong>. This makes it easier for new business owners as well as experienced traders from <strong>Rahim Yar Khan, Liaqat Pur, and Ahmed Pur East</strong> to enter the market without facing the pressure of full upfront payment.</span></p><p><span>Green Alliance Enterprises is not just developing a market; it is building a commercial destination for the future. For anyone looking to grow in the fruit and vegetable trade or invest in a high-potential business location, this is an opportunity worth exploring.</span></p>', '456 Maple Avenue, Downtown District', '{\"1\":\"gemini-generated-image-rubqierubqierubq-1.jpg\",\"2\":\"gemini-generated-image-rubqierubqierubq.jpg\",\"3\":\"gemini-generated-image-y2bj0ty2bj0ty2bj.jpg\"}', '\"[]\"', '0', '9.0', '3.0', '70', '290', '148900.00', '1', '1', '0', NULL, 'month', 'selling', NULL, 'Botble\\RealEstate\\Models\\Account', 'approved', NULL, '2027-03-26', '0', '1', '2026-05-29 08:48:44', '2026-08-16 10:48:00', '43.5373', '-76.6804', NULL, '92153', '1', '1', 'R0YHX9', ''),
('40', 'Horizon Pointe', 'rent', 'Exceptional residence in a prime location with easy access to schools, shopping, and public transportation. Recently renovated with high-end fixtures.', 'This stunning residence offers an unparalleled living experience in one of the most desirable locations. The thoughtfully designed floor plan maximizes space and functionality while maintaining an elegant aesthetic. Upon entering, you are greeted by soaring ceilings and an abundance of natural light that highlights the premium finishes throughout. The chef-inspired kitchen features top-of-the-line appliances, a large center island, and ample storage. The living areas are perfect for both intimate gatherings and large-scale entertaining. Each bedroom is generously sized with excellent closet space. The primary suite includes a luxurious bathroom with dual vanities, a soaking tub, and a separate shower. Outside, the property boasts professional landscaping, a private backyard, and a covered outdoor entertaining area. Smart home features, energy-efficient systems, and a two-car garage complete this exceptional offering.', '258 Spruce Court, Valley Green', '[\"properties\\/1.jpg\",\"properties\\/3.jpg\",\"properties\\/4.jpg\",\"properties\\/5.jpg\",\"properties\\/6.jpg\",\"properties\\/7.jpg\",\"properties\\/8.jpg\",\"properties\\/10.jpg\"]', '[{\"name\":{\"key\":\"name\",\"value\":\"First Floor\"},\"bedrooms\":{\"key\":\"bedrooms\",\"value\":\"3\"},\"bathrooms\":{\"key\":\"bathrooms\",\"value\":\"2\"},\"image\":{\"key\":\"image\",\"value\":\"properties\\/floor.png\"}},{\"name\":{\"key\":\"name\",\"value\":\"Second Floor\"},\"bedrooms\":{\"key\":\"bedrooms\",\"value\":\"2\"},\"bathrooms\":{\"key\":\"bathrooms\",\"value\":\"1\"},\"image\":{\"key\":\"image\",\"value\":\"properties\\/floor.png\"}}]', '0', '5.0', '9.0', '77', '540', '126700.00', NULL, '1', '0', '6', 'month', 'renting', '8', 'Botble\\RealEstate\\Models\\Account', 'approved', NULL, '2026-07-03', '0', '1', '2026-05-29 08:48:44', '2026-08-16 09:59:54', '43.697', '-76.722', NULL, '66037', '6', '6', 'DIIG9S', NULL);

