INSERT INTO `re_reviews` (`id`, `account_id`, `reviewable_type`, `reviewable_id`, `star`, `content`, `status`, `created_at`, `updated_at`) VALUES
('1067', '2', 'Botble\\RealEstate\\Models\\Property', '39', '5', 'Wonderful experience from viewing to move-in. The agent was professional and answered all my questions thoroughly.', 'approved', '2026-05-02 08:48:47', '2026-05-29 08:48:47'),
('1079', '6', 'Botble\\RealEstate\\Models\\Property', '38', '4', 'Quiet neighbors and a peaceful atmosphere. Perfect for working from home.', 'approved', '2026-03-09 08:48:47', '2026-05-29 08:48:47'),
('1083', '12', 'Botble\\RealEstate\\Models\\Property', '40', '4', 'Stunning views from the balcony. The interior design is modern and tasteful. Highly recommend for professionals seeking a quiet retreat.', 'approved', '2026-05-13 08:48:47', '2026-05-29 08:48:47'),
('1116', '7', 'Botble\\RealEstate\\Models\\Project', '3', '4', 'Looking forward to the next phase of this development. The first phase has been outstanding.', 'approved', '2026-02-19 08:48:47', '2026-05-29 08:48:47'),
('1143', '3', 'Botble\\RealEstate\\Models\\Property', '38', '1', 'Excellent value for money. The property exceeded my expectations in terms of quality and comfort. The landlord was very responsive and helpful throughout.', 'approved', '2026-04-09 08:48:47', '2026-05-29 08:48:47'),
('1154', '4', 'Botble\\RealEstate\\Models\\Project', '3', '3', 'The landscaping around this project is beautiful. Green spaces make the community feel alive.', 'approved', '2026-04-18 08:48:47', '2026-05-29 08:48:47'),
('1155', '12', 'Botble\\RealEstate\\Models\\Property', '39', '3', 'The property has great resale potential. Smart investment for the future.', 'approved', '2026-04-23 08:48:47', '2026-05-29 08:48:47');

-- Table structure for `revisions`
